-- Resources: Audience Listening tutorial guides (docs/resources-design.md
-- slice 5). This tool had zero guides before this migration. Content only;
-- upserts on slug, guarded by edited_since_release.

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'audience-listening-create-and-publish', 'guide'::public.rc_kind, 'Creating and publishing a query', 'Ask up to five questions, then publish as a standalone page or a Grove embed.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A query is a public listening initiative: up to five ordered questions, published as its own page or embedded in a Grove article, with the answers coming back to you here."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create a query"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the query list, select "},{"type":"text","text":"New query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in an internal title (for your own list) and a public title (what a listener sees), plus an optional public introduction and internal notes. Select "},{"type":"text","text":"Create query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You land on the new query''s Questions tab."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add questions"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a question''s prompt, and optionally public guidance, internal context (staff-only), a maximum answer length, and whether it''s required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Add question","marks":[{"type":"bold"}]},{"type":"text","text":". Repeat for up to five questions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reorder or duplicate a question with the buttons on its card, or remove one — before anyone has answered."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish it"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the query''s header — visible from any tab — select "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":". There''s no separate publish step; this is what makes the query live."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to the Share tab for a "},{"type":"text","text":"Copy link","marks":[{"type":"bold"}]},{"type":"text","text":" to the standalone public page, and a "},{"type":"text","text":"Copy embed code","marks":[{"type":"bold"}]},{"type":"text","text":" button for a ready-made Grove iframe snippet."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A draft query''s link and embed code don''t work yet — select "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" (always available) to see the public flow without publishing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a query has real submissions, question wording stays editable, but removing or reordering questions is no longer offered — an answer keeps the exact wording it was asked under."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The header''s action changes with status: open queries offer "},{"type":"text","text":"Close query","marks":[{"type":"bold"}]},{"type":"text","text":"; closed ones offer "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Archive query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{audience-listening.queries,audience-listening.query}'::text[], 10, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'audience-listening'
