insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'audience-listening-review-submissions', 'guide'::public.rc_kind, 'Reviewing submissions and answers', 'Open a participant''s submission, listen to each answer, and mark it reviewed.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every response to a query is a submission, made up of one answer per question it asked."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find a submission"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the query and select its "},{"type":"text","text":"Submissions","marks":[{"type":"bold"}]},{"type":"text","text":" tab — the count in the tab label tells you how many there are."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a participant''s name to open their submission."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review one"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The left column shows the participant''s details, their consent and attribution choices, and a note field only your staff can see."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The right column lists every question in order, each with an outcome — answered, incomplete, skipped, or not asked (a question added after this participant responded)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An answered question has an audio player, its duration and file size, and a link to download the original file."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark reviewed","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Flag","marks":[{"type":"bold"}]},{"type":"text","text":", and "},{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":" apply to the whole submission, at the top of the page; the same actions are also available per answer, further down."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"“Incomplete” means the upload started but never finished — the audio may not exist. The screen says so plainly rather than showing a broken player."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a question''s wording has changed since this answer was recorded, the answer shows the wording as it was asked, alongside how it reads today."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each answer has its own note field, separate from the submission-level one."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{audience-listening.query}'::text[], 20, 'editor'::public.rc_source, 'Initial version'
