insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'audience-listening-send-to-sourcework', 'guide'::public.rc_kind, 'Sending an answer to Sourcework', 'Hand one audio answer, or a whole query''s queue, to Sourcework for transcription.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An answer worth transcribing can be handed to Sourcework directly from its submission page — one answer at a time, or, for a query set to automatic transcription, in a batch."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Send one answer"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On a submission''s page, under an answered question, select "},{"type":"text","text":"Send to transcription","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"This creates a Sourcework project from the answer''s audio and starts transcription. You stay on the submission page — it doesn''t navigate you away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once it succeeds, the answer''s badge updates and an "},{"type":"text","text":"Open in Sourcework","marks":[{"type":"bold"}]},{"type":"text","text":" link appears, showing the project''s current status. Select it when you''re ready to leave for Sourcework."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Automatic queries"}]},{"type":"paragraph","content":[{"type":"text","text":"If the query''s settings have transcription set to automatic, every submitted answer is queued on its own. A banner above the Submissions list shows how many are queued, with a "},{"type":"text","text":"Send queued answers","marks":[{"type":"bold"}]},{"type":"text","text":" button that sends the whole batch in one click — still a manual click, since there''s no background job runner."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sending needs both Audience Listening and Sourcework access. Without the second, the button fails with a message telling you to ask an administrator for it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only what the participant consented to carries over — never their contact details, and their name or city only if they didn''t ask to stay anonymous."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a send fails, the button becomes "},{"type":"text","text":"Retry transcription","marks":[{"type":"bold"}]},{"type":"text","text":" and the error is shown right there on the page."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{audience-listening.query}'::text[], 30, 'editor'::public.rc_source, 'Initial version'
